/bin/zsh -lc "python3 - <<'PY'
from html.parser import HTMLParser
from pathlib import Path
import json

class InspectHTML(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.elements = []
        self.open_elements = []
        self.declarations = []
        self.issues = []
    def handle_decl(self, decl):
        self.declarations.append(decl)
    def handle_starttag(self, tag, attrs):
        element = {'tag': tag, 'attributes': dict(attrs), 'text': '', 'line': self.getpos()[0]}
        self.elements.append(element)
        if tag not in {'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'param', 'source', 'track', 'wbr'}:
            self.open_elements.append(element)
    def handle_endtag(self, tag):
        if not self.open_elements or self.open_elements[-1]['tag'] "'!= tag:
            self.issues.append('"'Unexpected closing tag: ' + tag)
        else:
            self.open_elements.pop()
    def handle_data(self, data):
        for element in self.open_elements:
            element['text'] += data

parser = InspectHTML()
parser.feed(Path('page.html').read_text(encoding='utf-8'))
parser.close()
counts = {}
for element in parser.elements:
    tag = element['tag']
    counts[tag] = counts.get(tag, 0) + 1
print(json.dumps({
    'declarations': parser.declarations,
    'element_counts': counts,
    'buttons_and_links': [e for e in parser.elements if e['tag'] in {'button', 'a'}],
    'forms_and_selection_controls': [e for e in parser.elements if e['tag'] in {'form', 'input', 'select', 'option'}],
    'scripts_and_inline_event_handlers': [e for e in parser.elements if e['tag'] == 'script' or any(a.startswith('on') for a in e['attributes'])],
    'document_metadata': [e for e in parser.elements if e['tag'] in {'title', 'meta', 'link', 'base'}],
    'explicit_tag_nesting_issues': parser.issues,
    'unclosed_explicit_tags': [e['tag'] for e in parser.open_elements],
    'limitation': 'Static source inspection only; not a browser, HTML conformance validator, or click test.'
}, ensure_ascii=False, indent=2))
