from html.parser import HTMLParser
from pathlib import Path
import json

class PageAudit(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.elements = []
        self.controls = []
        self.open_controls = []
        self.stack = []
        self.structure_issues = []
    def handle_starttag(self, tag, attrs):
        element = {'tag': tag, 'attrs': dict(attrs), 'line': self.getpos()[0]}
        self.elements.append(element)
        if tag in {'a', 'button', 'input', 'select', 'textarea'}:
            control = {**element, 'text': ''}
            self.controls.append(control)
            if tag "'!= '"'input':
                self.open_controls.append(control)
        if tag not in {'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'param', 'source', 'track', 'wbr'}:
            self.stack.append(tag)
    def handle_data(self, data):
        for control in self.open_controls:
            control['text'] += data
    def handle_endtag(self, tag):
        if not self.stack or self.stack[-1] "'!= tag:
            self.structure_issues.append('"'unexpected closing tag: ' + tag)
        else:
            self.stack.pop()
        if self.open_controls and self.open_controls[-1]['tag'] == tag:
            self.open_controls.pop()

raw = Path('page.html').read_bytes()
page = PageAudit()
page.feed(raw.decode('utf-8', errors='strict'))
page.close()
print(json.dumps({
    'utf8_decoding': 'passed',
    'explicit_tag_balance_issues': page.structure_issues,
    'unclosed_explicit_tags': page.stack,
    'controls': page.controls,
    'title_count': sum(e['tag'] == 'title' for e in page.elements),
    'meta': [e['attrs'] for e in page.elements if e['tag'] == 'meta'],
    'script_count': sum(e['tag'] == 'script' for e in page.elements),
    'form_count': sum(e['tag'] == 'form' for e in page.elements),
    'inline_event_handlers': [e for e in page.elements if any(k.startswith('on') for k in e['attrs'])],
    'download_links': [e for e in page.elements if e['tag'] == 'a' and 'download' in e['attrs']]
}, ensure_ascii=False, indent=2))
